/**
 * The words of a kind the catalog declares without a page (madarch-8bdc.2.5): the catalogue page lists every
 * declared kind, so a kind no stage fills yet still needs a name and a sentence in each interface language. The
 * English sentence is the row's own `definition`; only the Russian one is repeated here.
 */
interface CatalogWords {
  readonly en: readonly [string, string];
  readonly ru: readonly [string, string];
  /** The sentence saying what the kind is, in Russian; the English one is the row's `definition`. */
  readonly ruDescription: string;
}

