/**
 * The catalog the starter set holds: every declared row, each catalogue-only kind carrying its words so the
 * catalogue page can name and describe it. A kind without words stays as its row is, and the manifest reader's
 * finding names the declaration that left its translation out.
 */
export const CATALOG_KINDS: readonly CatalogKindData[] = DECLARED_KINDS.map((kind) => {
  if (kind.en !== undefined) return kind;
  const words = KIND_WORDS[kind.name];
  if (words === undefined) return kind;
  return { ...kind, en: words.en, ru: words.ru, describe: [kind.definition, words.ruDescription] };
});
